class MembershipLifecycleTest {
 JdbcTemplate db; MembershipService s; MembershipCheckoutService c; TransactionTemplate tx; PaymentAccountService payments;
 @BeforeEach void setup() throws Exception {
  DriverManagerDataSource ds=new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","sa","");db=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));
  db.execute("create table tenant(id bigint primary key)");db.execute("insert into tenant values(1),(2)");db.execute("create table store(id bigint primary key,tenant_id bigint,name varchar(50),unique(tenant_id,id))");db.execute("insert into store values(1,1,'one'),(2,1,'two')");
  String schema=new String(Files.readAllBytes(Paths.get("../../../database/migrations/20261117_02_membership.sql")),java.nio.charset.StandardCharsets.UTF_8);for(String sql:schema.split(";"))if(sql.trim().startsWith("CREATE TABLE"))db.execute(sql);
  db.execute("create table orders(id bigint,tenant_id bigint,user_id bigint,store_id bigint,number varchar(20),amount decimal(12,2),status int,order_time timestamp)");
  payments=mock(PaymentAccountService.class);when(payments.channelForNewOrders()).thenReturn("MOCK");when(payments.currentAccountId()).thenReturn("test-account");s=new MembershipService(db,new ObjectMapper(),payments,mock(RbacService.class));s.channelSettings=mock(PaymentChannelSettings.class);c=new MembershipCheckoutService(s);scope(1,1,1);
 }
 @AfterEach void cleanup(){RequestScope.clear();org.springframework.web.context.request.RequestContextHolder.resetRequestAttributes();}
 void scope(long tenant,long user,long store){RequestScope.set(new RequestScope(null,user,tenant,store,Collections.emptySet()));}
 <T>T run(Supplier<T> f){return tx.execute(st->f.get());}
 void run(Runnable f){tx.executeWithoutResult(st->f.run());}
 Map<String,Object> body(Object...a){Map<String,Object>b=new LinkedHashMap<>();for(int i=0;i<a.length;i+=2)b.put(a[i].toString(),a[i+1]);return b;}
 long join(){run(()->s.join(body("name","Alice","phone","13800000000")));return MembershipService.n(s.own(),"id");}
 long recharge(long amount,long gift){long plan=s.insert("insert into member_recharge_plan(tenant_id,name,amount,gift_amount) values(1,'test',?,?)",amount,gift);Map<String,Object>r=run(()->s.recharge(body("planId",plan,"requestId","r"+plan)));long id=Long.parseLong(r.get("id").toString());run(()->s.mockRecharge(id,body("outcome","SUCCESS")));return id;}
 Orders order(long id,MembershipCheckoutService.Quote q){Orders o=Orders.builder().id(id).tenantId(1L).storeId(1L).userId(1L).paymentChannel("MOCK").amount(q.getAmount()).build();run(()->c.reserve(o,q));return o;}
 @Test void rechargeReplayCheckoutCompleteRefundRestoresOriginalBatch(){long mid=join(),batch=recharge(10000,1000);long ledgerCount=db.queryForObject("select count(*) from member_asset_ledger",Long.class);run(()->s.mockRecharge(batch,body("outcome","SUCCESS")));assertEquals(ledgerCount,db.queryForObject("select count(*) from member_asset_ledger",Long.class));MembershipCheckoutService.Quote q=c.quote(new BigDecimal("105"),BigDecimal.ZERO,"PICKUP",null,0,true);assertEquals(new BigDecimal("0.00"),q.asMap().get("externalAmount"));Orders o=order(50,q);run(()->c.paid(o));run(()->c.paid(o));run(()->c.complete(o));run(()->c.complete(o));assertEquals(100,MembershipService.n(s.account(mid,"MOCK",false),"points"));run(()->c.refund(o));run(()->c.refund(o));Map<String,Object>w=s.account(mid,"MOCK",false);assertEquals(10000,MembershipService.n(w,"principal"));assertEquals(1000,MembershipService.n(w,"gift"));assertEquals(0,MembershipService.n(w,"points"));Map<String,Object>b=s.ownedRecharge(batch,false);assertEquals(10000,MembershipService.n(b,"principal_remaining"));assertEquals(1000,MembershipService.n(b,"gift_remaining"));assertEquals(0,MembershipService.n(s.member(mid,false),"total_spent"));run(()->s.refundRecharge(batch,body("requestId","refund","reason","test"),false));assertEquals(0,MembershipService.n(s.account(mid,"MOCK",false),"principal"));}
 @Test void rejectedReplayRollsBackAndTenantEnvironmentCannotLeak(){long mid=join();long plan=s.insert("insert into member_recharge_plan(tenant_id,name,amount) values(1,'x',100)");Map<String,Object>b=body("planId",plan,"requestId","same");run(()->s.recharge(b));assertThrows(IllegalArgumentException.class,()->run(()->s.recharge(body("planId",999,"requestId","same"))));scope(2,1,2);assertNull(s.own());assertThrows(IllegalArgumentException.class,()->s.member(mid,false));scope(1,1,2);assertNotNull(s.own());when(payments.channelForNewOrders()).thenReturn("WECHAT");assertEquals(0,MembershipService.n(s.account(mid,"WECHAT",false),"principal"));}
 @Test void couponClaimSnapshotFrozenReleaseAndExpiry(){long mid=join();long template=s.insert("insert into coupon_template(tenant_id,name,type,`value`,min_spend,start_time,end_time,total_stock,store_ids,fulfillment_types) values(1,'Coupon','FIXED',100,100,CURRENT_TIMESTAMP-INTERVAL '1' DAY,CURRENT_TIMESTAMP+INTERVAL '1' DAY,1,'[]','[]')");Map<String,Object>b=body("requestId","c1");Map<String,Object>coupon=run(()->s.claim(template,b,false));assertEquals(coupon.get("id"),run(()->s.claim(template,b,false)).get("id"));assertThrows(IllegalArgumentException.class,()->run(()->s.claim(template,body("requestId","c2"),false)));long cid=Long.parseLong(coupon.get("id").toString());MembershipCheckoutService.Quote q=c.quote(new BigDecimal("5"),new BigDecimal("2"),"PICKUP",cid,0,false);assertEquals(new BigDecimal("6.00"),q.getAmount());Orders o=order(51,q);assertThrows(com.junzhou.exception.OrderBusinessException.class,()->c.quote(new BigDecimal("5"),BigDecimal.ZERO,"PICKUP",cid,0,false));run(()->c.release(o));run(()->c.release(o));assertEquals("AVAILABLE",s.one("select status from member_coupon where id=?",cid).get("status"));assertEquals(0,MembershipService.n(s.account(mid,"MOCK",false),"points_held"));}
 @Test void competingQuotesCannotOverspendAndDisabledStillRefunds(){long mid=join();recharge(1000,0);MembershipCheckoutService.Quote q1=c.quote(new BigDecimal("10"),BigDecimal.ZERO,"PICKUP",null,0,true),q2=c.quote(new BigDecimal("10"),BigDecimal.ZERO,"PICKUP",null,0,true);Orders o=order(70,q1);assertThrows(com.junzhou.exception.OrderBusinessException.class,()->order(71,q2));run(()->c.paid(o));db.update("update member set status=0 where id=?",mid);assertThrows(com.junzhou.exception.OrderBusinessException.class,()->c.quote(new BigDecimal("10"),BigDecimal.ZERO,"PICKUP",null,0,true));run(()->c.refund(o));assertEquals(1000,MembershipService.n(s.account(mid,"MOCK",false),"principal"));}
 @Test void spentEarnedPointsBecomeDebtWithoutBlockingRefund(){long mid=join();recharge(2000,0);Orders o=order(80,c.quote(new BigDecimal("10"),BigDecimal.ZERO,"PICKUP",null,0,true));run(()->c.paid(o));run(()->c.complete(o));run(()->s.ledger(mid,"MOCK","POINTS",-10,"spent","exchange",1));run(()->c.refund(o));assertEquals(10,MembershipService.n(s.account(mid,"MOCK",false),"points_debt"));run(()->s.creditPoints(mid,"MOCK",6,"next",1));assertEquals(4,MembershipService.n(s.account(mid,"MOCK",false),"points_debt"));assertEquals(0,MembershipService.n(s.account(mid,"MOCK",false),"points"));}

 @Test void storeOnlyReaderSeesAssociatedProfilesWithoutTenantAssets(){long mid=join();recharge(1000,0);scope(1,2,2);long other=join();RequestScope.set(new RequestScope(10L,null,1L,1L,new HashSet<>(Arrays.asList(1L,2L))));org.springframework.mock.web.MockHttpServletRequest req=new org.springframework.mock.web.MockHttpServletRequest();org.springframework.web.context.request.RequestContextHolder.setRequestAttributes(new org.springframework.web.context.request.ServletRequestAttributes(req));com.junzhou.security.RbacRequestContext.begin(req);Map<Long,Set<com.junzhou.security.PermissionAction>> actions=new HashMap<>();actions.put(1L,EnumSet.of(com.junzhou.security.PermissionAction.MEMBER_READ));actions.put(2L,EnumSet.of(com.junzhou.security.PermissionAction.DISH_READ));Map<Long,String> names=new HashMap<>();names.put(1L,"one");names.put(2L,"two");com.junzhou.security.RbacRequestContext.store(new com.junzhou.security.AuthorizationSnapshot(1L,10L,names,actions,Collections.emptySet()));Map<String,Object>page=s.pageMembers(Collections.emptyMap());assertEquals(1L,page.get("total"));Map<String,Object> row=((List<Map<String,Object>>)page.get("records")).get(0);assertFalse(row.containsKey("balance"));assertFalse(row.containsKey("points"));assertNotEquals("13800000000",row.get("phone"));assertThrows(SecurityException.class,()->s.detail(other));assertThrows(SecurityException.class,()->run(()->s.adjust(mid,body("amount",10,"reason","test","requestId","staff"),false)));}
 @Test void concurrentReserveSerializesAtAccountAndOnlyOneSpends()throws Exception {join();recharge(1000,0);MembershipCheckoutService.Quote a=c.quote(new BigDecimal("10"),BigDecimal.ZERO,"PICKUP",null,0,true),b=c.quote(new BigDecimal("10"),BigDecimal.ZERO,"PICKUP",null,0,true);ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{List<Future<Boolean>>results=new ArrayList<>();for(int i=0;i<2;i++){final int slot=i;results.add(pool.submit(()->{scope(1,1,1);start.await();try{order(100+slot,slot==0?a:b);return true;}catch(com.junzhou.exception.OrderBusinessException e){return false;}finally{RequestScope.clear();}}));}start.countDown();int success=0;for(Future<Boolean>r:results)if(r.get(10,TimeUnit.SECONDS))success++;assertEquals(1,success);assertEquals(1000L,db.queryForObject("select principal_held from member_wallet",Long.class));}finally{pool.shutdownNow();}}
 @Test void nonmemberAndFeeOnlyQuotesDoNotCreateMembership(){MembershipCheckoutService.Quote q=c.quote(new BigDecimal("10"),new BigDecimal("2"),"PICKUP",null,0,false);assertEquals(new BigDecimal("12.00"),q.getAmount());assertEquals(new BigDecimal("12.00"),q.asMap().get("externalAmount"));Orders o=Orders.builder().id(99L).tenantId(1L).storeId(1L).userId(1L).paymentChannel("MOCK").build();run(()->c.reserve(o,q));assertNull(s.own());assertEquals(0L,db.queryForObject("select count(*) from member_order_asset",Long.class));}

 @Test void refundBeforePaidReleasesHoldsAndLatePaidCannotConsumeAgain(){long mid=join();recharge(1000,0);Orders o=order(150,c.quote(new BigDecimal("10"),BigDecimal.ZERO,"PICKUP",null,0,true));run(()->c.refund(o));run(()->c.paid(o));run(()->c.refund(o));Map<String,Object>w=s.account(mid,"MOCK",false);assertEquals(1000,MembershipService.n(w,"principal"));assertEquals(0,MembershipService.n(w,"principal_held"));assertEquals("RELEASED",s.one("select status from member_order_asset where order_id=150").get("status"));}
 @Test void mockSpendAndLevelNeverAffectWechatQuote(){long mid=join();db.update("update member_level set discount_percent=80 where tenant_id=1 and threshold=50000");Orders o=order(160,c.quote(new BigDecimal("600"),BigDecimal.ZERO,"PICKUP",null,0,false));run(()->c.paid(o));run(()->c.complete(o));assertEquals(new BigDecimal("8.00"),c.quote(new BigDecimal("10"),BigDecimal.ZERO,"PICKUP",null,0,false).getAmount());when(payments.channelForNewOrders()).thenReturn("WECHAT");assertEquals(new BigDecimal("10.00"),c.quote(new BigDecimal("10"),BigDecimal.ZERO,"PICKUP",null,0,false).getAmount());Map<String,Object>member=(Map<String,Object>)s.profile().get("member");assertEquals(new BigDecimal("0.00"),member.get("totalSpent"));assertEquals(0L,member.get("orderCount"));}

 void adminScope(){RequestScope.set(new RequestScope(10L,null,1L,1L,Collections.singleton(1L)));org.springframework.mock.web.MockHttpServletRequest req=new org.springframework.mock.web.MockHttpServletRequest();org.springframework.web.context.request.RequestContextHolder.setRequestAttributes(new org.springframework.web.context.request.ServletRequestAttributes(req));com.junzhou.security.RbacRequestContext.begin(req);Map<Long,String>stores=Collections.singletonMap(1L,"one");Map<Long,Set<com.junzhou.security.PermissionAction>>actions=Collections.singletonMap(1L,EnumSet.allOf(com.junzhou.security.PermissionAction.class));com.junzhou.security.RbacRequestContext.store(new com.junzhou.security.AuthorizationSnapshot(1L,10L,stores,actions,EnumSet.allOf(com.junzhou.security.PermissionAction.class)));}
 @Test void batchIssueAndSingleClaimUseSameLockOrderAndCommitAtomically()throws Exception {long one=join();scope(1,2,2);long two=join();long template=s.insert("insert into coupon_template(tenant_id,name,type,`value`,start_time,end_time,total_stock,per_member_limit,store_ids,fulfillment_types) values(1,'Concurrent','FIXED',100,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP+INTERVAL '1' DAY,3,2,'[]','[]')");ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{Future<?>batch=pool.submit(()->{adminScope();try{start.await();run(()->s.issue(template,body("memberIds",Arrays.asList(one,two),"requestId","batch")));}catch(InterruptedException ex){throw new RuntimeException(ex);}finally{RequestScope.clear();org.springframework.web.context.request.RequestContextHolder.resetRequestAttributes();}});Future<?>single=pool.submit(()->{scope(1,2,2);try{start.await();run(()->s.claim(template,body("requestId","single"),false));}catch(InterruptedException ex){throw new RuntimeException(ex);}finally{RequestScope.clear();}});start.countDown();batch.get(10,TimeUnit.SECONDS);single.get(10,TimeUnit.SECONDS);assertEquals(3L,db.queryForObject("select count(*) from member_coupon",Long.class));assertEquals(3L,db.queryForObject("select issued from coupon_template",Long.class));}finally{pool.shutdownNow();}}

 @Test void manualMockLevelDoesNotLeakIntoRealEnvironment(){long mid=join();long gold=db.queryForObject("select id from member_level where tenant_id=1 and threshold=200000",Long.class);db.update("update member_level set discount_percent=70 where id=?",gold);adminScope();run(()->s.updateAdmin(mid,body("name","Alice","phone","13800000000","levelId",gold,"version",0)));Map<String,Object>page=s.pageMembers(Collections.singletonMap("levelId",Long.toString(gold)));assertEquals(1L,page.get("total"));scope(1,1,1);assertEquals(new BigDecimal("7.00"),c.quote(new BigDecimal("10"),BigDecimal.ZERO,"PICKUP",null,0,false).getAmount());when(payments.channelForNewOrders()).thenReturn("WECHAT");assertEquals(new BigDecimal("10.00"),c.quote(new BigDecimal("10"),BigDecimal.ZERO,"PICKUP",null,0,false).getAmount());}

 @Test void betterLevelBenefitLeavesWorseSelectedCouponAvailable(){long mid=join();db.update("update member_level set discount_percent=80 where tenant_id=1 and threshold=0");long template=s.insert("insert into coupon_template(tenant_id,name,type,`value`,start_time,end_time,total_stock,store_ids,fulfillment_types) values(1,'Small','FIXED',100,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP+INTERVAL '1' DAY,1,'[]','[]')");Map<String,Object>coupon=run(()->s.claim(template,body("requestId","level-choice"),false));long cid=Long.parseLong(coupon.get("id").toString());MembershipCheckoutService.Quote quote=c.quote(new BigDecimal("10"),BigDecimal.ZERO,"PICKUP",cid,0,false);assertEquals(new BigDecimal("8.00"),quote.getAmount());assertNull(quote.asMap().get("appliedCouponId"));Orders o=order(170,quote);run(()->c.paid(o));assertEquals("AVAILABLE",s.one("select status from member_coupon where id=?",cid).get("status"));}

 @Test void pointsUseWholeConversionUnitsAndExcludeFeesFromCap(){long mid=join();run(()->s.creditPoints(mid,"MOCK",1000,"seedPoints",1));MembershipCheckoutService.Quote below=c.quote(new BigDecimal("9.99"),new BigDecimal("20"),"PICKUP",null,0,false);assertEquals(0L,below.asMap().get("maxDeductiblePoints"));assertThrows(com.junzhou.exception.OrderBusinessException.class,()->c.quote(new BigDecimal("9.99"),new BigDecimal("20"),"PICKUP",null,100,false));assertThrows(com.junzhou.exception.OrderBusinessException.class,()->c.quote(new BigDecimal("10"),BigDecimal.ZERO,"PICKUP",null,99,false));MembershipCheckoutService.Quote q=c.quote(new BigDecimal("10"),new BigDecimal("2"),"PICKUP",null,100,false);assertEquals(new BigDecimal("11.00"),q.getAmount());assertEquals(100L,q.asMap().get("maxDeductiblePoints"));Orders o=order(180,q);assertEquals(100,MembershipService.n(s.account(mid,"MOCK",false),"points_held"));run(()->c.release(o));assertEquals(1000,MembershipService.n(s.account(mid,"MOCK",false),"points"));assertEquals(0,MembershipService.n(s.account(mid,"MOCK",false),"points_held"));}
 @Test void percentageDiscountRoundsPayableHalfUpAndNeverDiscountsFees(){join();long template=s.insert("insert into coupon_template(tenant_id,name,type,`value`,start_time,end_time,total_stock,store_ids,fulfillment_types) values(1,'Half','DISCOUNT',50,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP+INTERVAL '1' DAY,1,'[]','[]')");Map<String,Object>coupon=run(()->s.claim(template,body("requestId","round"),false));long cid=Long.parseLong(coupon.get("id").toString());MembershipCheckoutService.Quote q=c.quote(new BigDecimal("0.05"),new BigDecimal("2"),"PICKUP",cid,0,false);assertEquals(new BigDecimal("2.03"),q.getAmount());assertEquals(new BigDecimal("0.02"),q.asMap().get("couponDiscount"));}

 @org.springframework.context.annotation.Configuration
 @org.springframework.transaction.annotation.EnableTransactionManagement(proxyTargetClass=true)
 static class TransactionProxyConfiguration {}
 @Test void realSpringTransactionProxiesRunCheckoutWithoutDirectTargetFieldAccess(){
  try(org.springframework.context.annotation.AnnotationConfigApplicationContext context=new org.springframework.context.annotation.AnnotationConfigApplicationContext()){
   context.registerBean(JdbcTemplate.class,()->db);
   context.registerBean(ObjectMapper.class,(java.util.function.Supplier<ObjectMapper>)()->new ObjectMapper());
   context.registerBean(PaymentAccountService.class,()->payments);
   context.registerBean(RbacService.class,()->mock(RbacService.class));
   context.registerBean(PaymentChannelSettings.class,()->mock(PaymentChannelSettings.class));
   context.registerBean("transactionManager",org.springframework.transaction.PlatformTransactionManager.class,()->tx.getTransactionManager());
   context.register(TransactionProxyConfiguration.class,MembershipService.class,MembershipCheckoutService.class);
   context.refresh();
   MembershipService service=context.getBean(MembershipService.class);
   MembershipCheckoutService checkout=context.getBean(MembershipCheckoutService.class);
   assertTrue(org.springframework.aop.support.AopUtils.isCglibProxy(service));
   assertTrue(org.springframework.aop.support.AopUtils.isCglibProxy(checkout));
   assertSame(db,service.jdbc());
   service.join(body("name","Proxy Alice"));long mid=MembershipService.n(service.own(),"id");
   long plan=service.insert("insert into member_recharge_plan(tenant_id,name,amount,gift_amount) values(1,'Proxy plan',1000,100)");
   Map<String,Object> recharge=service.recharge(body("planId",plan,"requestId","proxy-recharge"));long rid=Long.parseLong(recharge.get("id").toString());
   service.mockRecharge(rid,body("outcome","SUCCESS"));
   long template=service.insert("insert into coupon_template(tenant_id,name,type,`value`,start_time,end_time,total_stock,store_ids,fulfillment_types) values(1,'Proxy coupon','FIXED',100,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP+INTERVAL '1' DAY,1,'[]','[]')");
   Map<String,Object> coupon=service.claim(template,body("requestId","proxy-coupon"),false);long cid=Long.parseLong(coupon.get("id").toString());
   MembershipCheckoutService.Quote quote=checkout.quote(new BigDecimal("13"),BigDecimal.ZERO,"PICKUP",cid,0,true);
   Orders order=Orders.builder().id(190L).tenantId(1L).storeId(1L).userId(1L).paymentChannel("MOCK").amount(quote.getAmount()).build();
   // No TransactionTemplate around these calls: the same Spring advice used by HTTP must open the transactions.
   checkout.reserve(order,quote);assertEquals(1000,MembershipService.n(service.account(mid,"MOCK",false),"principal_held"));
   checkout.paid(order);checkout.complete(order);checkout.refund(order);checkout.refund(order);
   Map<String,Object> wallet=service.account(mid,"MOCK",false);assertEquals(1000,MembershipService.n(wallet,"principal"));assertEquals(100,MembershipService.n(wallet,"gift"));assertEquals(0,MembershipService.n(wallet,"principal_held"));assertEquals(0,MembershipService.n(wallet,"points"));
   assertEquals("AVAILABLE",service.one("select status from member_coupon where id=?",cid).get("status"));
   assertEquals("REFUNDED",service.one("select status from member_order_asset where order_id=190").get("status"));
  }
 }
}
